31:
SELECT MaHS, ChiNhanh, TrangThai
FROM HoSo
ORDER BY MaHS;

34:
SELECT MaHS, XuLyPhut, SLAPhut FROM HoSo
WHERE TrangThai = 'Đã đóng'
ORDER BY XuLyPhut DESC, MaHS LIMIT 3;

36:
SELECT MaHS, CASE WHEN TrangThai <> 'Đã đóng' THEN 'Đang mở'
  WHEN XuLyPhut <= SLAPhut THEN 'Đạt' ELSE 'Trễ' END AS Nhom
FROM HoSo ORDER BY MaHS;

37:
SELECT SUM(XuLyPhut) AS Tong, AVG(XuLyPhut) AS TrungBinh,
       MIN(XuLyPhut) AS NhanhNhat, MAX(XuLyPhut) AS ChamNhat
FROM HoSo WHERE TrangThai = 'Đã đóng';

38:
SELECT ChiNhanh, COUNT(*) AS TiepNhan,
       SUM(CASE WHEN TrangThai = 'Đã đóng' THEN 1 ELSE 0 END) AS DaDong
FROM HoSo GROUP BY ChiNhanh ORDER BY ChiNhanh;

40:
SELECT a.MaGD, a.SoTienVND AS NoiBoVND, b.SoTienVND AS DoiTacVND
FROM NoiBo a JOIN DoiTac b ON a.MaGD = b.MaGD
ORDER BY a.MaGD;

41:
SELECT a.MaGD, a.SoTienVND FROM NoiBo a
LEFT JOIN DoiTac b ON a.MaGD = b.MaGD
WHERE b.MaGD IS NULL;

43:
SELECT MaHS, ChiNhanh, XuLyPhut FROM HoSo
WHERE XuLyPhut > (SELECT AVG(XuLyPhut) FROM HoSo)
ORDER BY XuLyPhut DESC;

44:
WITH nb AS (
  SELECT MaGD, COUNT(*) AS n, SUM(SoTienVND) AS tien FROM NoiBo GROUP BY MaGD
), dt AS (
  SELECT MaGD, COUNT(*) AS n, SUM(SoTienVND) AS tien FROM DoiTac GROUP BY MaGD
), ma AS (SELECT MaGD FROM nb UNION SELECT MaGD FROM dt)
SELECT ma.MaGD, COALESCE(nb.n,0) AS LanNB, COALESCE(dt.n,0) AS LanDT,
       COALESCE(nb.tien,0)-COALESCE(dt.tien,0) AS ChenhVND
FROM ma LEFT JOIN nb USING (MaGD) LEFT JOIN dt USING (MaGD)
ORDER BY ma.MaGD;
